version.transform:
(
  $timeZone := setting.edges.node.defaultValue;
  $shifts := productionSetup.edges[0].node.workcenter.shiftGroup.shifts.edges.node;

  $dateToInt := function($hour, $minute){
      ($string($hour) & $pad($string($minute), -2, "0"))~>$number
   };
  $findCreditAtAll := function($start, $timeZone, $v){(
    $dateInTimeZone := $momentTz($start, undefined, $timeZone);
    $daysDaysFromStartDate := $v.day;

    $shiftCrossesMidnight := $v.endHour < $v.startHour;
    $offsetToUse := $shiftCrossesMidnight? 
      $v.creditAtStart? 0 : 1
    :
    0;

    $dateInTimeZone.add($offsetToUse+$v.day, "day").startOf("day").format();

  )};
  $findCreditAt := $findCreditAtAll($state.context.startTime, $timeZone, ?);
  $getShiftsInRange := function($shifts){(
    $map(
      $shifts,
      function($v){(
        $startInTimeZone := $momentTz($state.context.startTime, undefined, $timeZone);
        $endInTimeZone := $momentTz($state.context.endTime, undefined, $timeZone);
        $dayDiff := $endInTimeZone.date() - $startInTimeZone.date();

        /*If the range spans more then a single day then we need to condsider that the 1D collision dection wont work.
          Break this into once per day per shift to decide if we should include a shift more then once.
        */
        [0..$dayDiff].(
          /*if this is the first day of the range we should use the start time otherwise we can just use the start of the day*/ 
          $start := $=0? $dateToInt($startInTimeZone.hour(), $startInTimeZone.minute()): 0;
          /*Same logic as the start time just for the end of the day*/
          $end := $=$dayDiff? $dateToInt($endInTimeZone.hour(), $endInTimeZone.minute()): 2359;

          $shiftStart := $dateToInt($v.startHour, $v.startMinute);
          $shiftEnd := $dateToInt($v.endHour, $v.endMinute);

          /* Its possible we might hit a shift twice if it spans more then one day here we adjust the day that it counts towards based on the creditAt */
          $result := ($shiftStart < $shiftEnd and $end >= $shiftStart and $shiftEnd > $start)? 
            {"hit": true, "day": $} :
          ($shiftStart > $shiftEnd and ($end >= $shiftStart or $start >= $shiftStart )  )?
            {"hit": true, "day": $v.creditAtStart? $ : $+1} :
          ($shiftStart > $shiftEnd and ($end < $shiftEnd or $start < $shiftEnd )  )?
            {"hit": true, "day": $v.creditAtStart? $-1 : $} :
            {"hit": false};


           $result.hit?   $merge([$v, {"day": $result.day, "start": $start, "end": $end, "ss": $shiftStart, "se": $shiftEnd, "hit": $result.hit}]) 
        );

      )}
  )
    ~>$flatten
    ~>$uniqBy(?, $pick(?, ["id", "day"])~>$values~>$join(?, "::") )
    ~>$filter($isNil~>$not)^(day, startHour, startMinute)
     ~> | $ | { "creditAt": $findCreditAt($) } | 
  )};




)
